"""Therapy part 5: settings and the 20 tables with calculated columns."""
import sys, os; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from lib import *
from th5_lists import *
import th5_data as D

def CA(k, label, fmt, f, w=12, **kw): return CALC(k, label, fmt, f, w, **kw)
def LKT(src, kc, my): return 'IFERROR(INDEX({range:%s},MATCH({col:%s},{range:%s},0))&"","")' % (src, my, kc)
MS = 'DATE(YEAR({today}),MONTH({today}),1)'
LM = 'EDATE(%s,-1)' % MS

settings = [
    S('company', 'Your practice name', 'text', COMPANY), S('target_utilisation', 'Target booked share of cap (top of healthy band)', 'pct', 0.85),
    S('util_idle_below', 'Idle band: booked share of cap below', 'pct', 0.70), S('util_healthy_from', 'Healthy band: booked share of cap from', 'pct', 0.75),
    S('util_strain_above', 'Strain band: booked share of cap above', 'pct', 0.90), S('missed_session_target', 'Target missed and late-cancelled share of booked sessions', 'pct', 0.10),
    S('profit_target', 'Target profit margin', 'pct', 0.15), S('pay_share_target', 'Target pay share of revenue', 'pct', 0.55),
    S('target_tolerance', 'How far from a target still counts as healthy', 'pct', 0.05), S('employer_cost_pct', 'Employer costs on salaries and hourly pay', 'pct', 0.12),
    S('room_cost_hour', 'Cost of one hour of room time', 'money', 12), S('admin_cost', 'Admin cost per booked session', 'money', 6),
    S('card_fee_pct', 'Card fee on a card payment', 'pct', 0.025), S('supervision_rate', 'Cost of one hour of supervision for the associate', 'money', 60),
    S('retention_target', 'Target retention to 6 sessions', 'pct', 0.70), S('rebook_target', 'Target share rebooked within 14 days', 'pct', 0.75),
    S('rev_hour_target', 'Target revenue per clinical hour', 'money', 130), S('admin_share_target', 'Admin share of clinician time that is accepted', 'pct', 0.20),
    S('note_late_limit', 'Late notes a clinician may have before a review', 'int', 1)]
assert len(settings) <= 20

def T_(key, sheet, title, hint, cols, demo, rows, alerts=None):
    assert len(hint) <= 200, (key, len(hint))
    return T(key, sheet, title, hint, cols, demo, rows, alerts)

def _role(role, col): return 'IFERROR(INDEX({range:team.%s},MATCH(%s,{range:team.role},0))&"","")' % (col, tok('role', role))
def PH(me): return CA('phone', 'Phone', 'text', LKT('team.phone', 'team.name', me), 18)
def OWN(): return [CA('owner', 'Owner', 'text', _role('Owner clinician', 'name'), 18), CA('owner_phone', 'Owner phone', 'text', _role('Owner clinician', 'phone'), 18)]
def ACC(): return [CA('accountant', 'Accountant', 'text', _role('Accountant', 'name'), 18), CA('accountant_phone', 'Accountant phone', 'text', _role('Accountant', 'phone'), 18)]
def CRD(): return [CA('coord', 'Coordinator', 'text', _role('Practice coordinator', 'name'), 18), CA('coord_phone', 'Coordinator phone', 'text', _role('Practice coordinator', 'phone'), 18)]
def CMW(col, extra): return 'SUMIFS({range:clin_months.%s},{range:clin_months.clinician},{col:clinician},%s)' % (col, extra)
PREV3 = '{range:clin_months.month},">="&EDATE({col:month},-3),{range:clin_months.month},"<"&{col:month}'
R12 = '{range:clin_months.month},">"&EDATE({col:month},-12),{range:clin_months.month},"<="&{col:month}'
YAGO = '{range:clin_months.month},EDATE({col:month},-12)'

clin_cols = [C('row_id', 'Row ID', 'text', 9, required=True), C('month', 'Month', 'date', 11), LST('clinician', 'Clinician', 'clin', 16), C('working_weeks', 'Working weeks', 'int', 9),
    C('capacity', 'Capacity (session cap)', 'int', 10), C('booked', 'Booked sessions', 'int', 9), C('attended', 'Attended', 'int', 9), C('cancelled', 'Cancelled', 'int', 9), C('late_cancels', 'Late cancels', 'int', 9),
    C('no_shows', 'No-shows', 'int', 9), C('clinical_hours', 'Clinical hours', 'num', 10), C('revenue', 'Revenue', 'money', 12), C('new_clients', 'New clients', 'int', 9), C('discharges', 'Discharges', 'int', 10),
    C('late_notes', 'Late notes', 'int', 9),
    CA('share_of_cap', 'Utilization Rate', 'pct', 'IF({col:capacity}>0,{col:booked}/{col:capacity},0)', 11),
    CA('band', 'Utilization band', 'text', BAND('{col:share_of_cap}'), 14),
    CA('attendance_rate', 'Attendance rate', 'pct', 'IF({col:attended}+{col:late_cancels}+{col:no_shows}>0,{col:attended}/({col:attended}+{col:late_cancels}+{col:no_shows}),0)', 10),
    CA('missed_share', 'Missed share of booked', 'pct', 'IF({col:booked}>0,({col:late_cancels}+{col:no_shows})/{col:booked},0)', 10),
    CA('rev_per_hour', 'Revenue per clinical hour', 'money', 'IF({col:clinical_hours}>0,{col:revenue}/{col:clinical_hours},0)', 12),
    CA('rph_avg3', 'Per hour, 3-month average', 'money', 'IFERROR(%s/%s,"")' % (CMW('revenue', PREV3), CMW('clinical_hours', PREV3)), 12),
    CA('rph_last_year', 'Per hour, same month last year', 'money', 'IFERROR(%s/%s,"")' % (CMW('revenue', YAGO), CMW('clinical_hours', YAGO)), 12),
    CA('rph_vs_avg3', 'Per hour vs 3-month average', 'pct', 'IF(ISNUMBER({col:rph_avg3}),{col:rev_per_hour}/{col:rph_avg3}-1,"")', 12),
    CA('rph_vs_last_year', 'Per hour vs same month last year', 'pct', 'IF(ISNUMBER({col:rph_last_year}),{col:rev_per_hour}/{col:rph_last_year}-1,"")', 12),
    CA('share_avg3', 'Utilization, 3-month average', 'pct', 'IFERROR(%s/%s,"")' % (CMW('booked', PREV3), CMW('capacity', PREV3)), 11),
    CA('share_last_year', 'Utilization, same month last year', 'pct', 'IFERROR(%s/%s,"")' % (CMW('booked', YAGO), CMW('capacity', YAGO)), 11),
    CA('attended_12m', 'Attended, 12 months to this month', 'int', CMW('attended', R12), 12), CA('hours_12m', 'Clinical hours, 12 months', 'num', CMW('clinical_hours', R12), 11),
    CA('revenue_12m', 'Revenue, 12 months', 'money', CMW('revenue', R12), 12),
    CA('strain_line', 'Strain line', 'pct', '{set:util_strain_above}', 8), PH('clinician')] + OWN()

pay_cols = [C('pay_id', 'Pay ID', 'text', 9, required=True), C('month', 'Month', 'date', 11), LST('person', 'Person', 'staff', 16), LST('pay_type', 'Pay type', 'paykind', 14), C('sessions', 'Sessions', 'int', 9),
    C('hours', 'Hours', 'num', 9), C('fees_charged', 'Fees charged', 'money', 12), C('split_pct', 'Split', 'pct', 8), C('amount', 'Pay amount', 'money', 12), C('employer_cost', 'Employer cost', 'money', 12),
    C('paid_on', 'Paid on', 'date', 11), LST('status', 'Status', 'payst', 10),
    CA('pay_per_session', 'Pay per session', 'money', 'IF({col:sessions}>0,{col:amount}/{col:sessions},"")', 11),
    CA('all_in_pay', 'Pay with employer cost', 'money', '{col:amount}+{col:employer_cost}', 12),
    CA('pay_share', 'Pay share of fees', 'pct', 'IF({col:fees_charged}>0,({col:amount}+{col:employer_cost})/{col:fees_charged},"")', 10), PH('person')] + ACC() + CRD() + OWN()

alln_cols = [C('allin_id', 'Row ID', 'text', 9, required=True), C('month', 'Month', 'date', 11), LST('clinician', 'Clinician', 'clin', 16), LST('pay_type', 'Pay type', 'cpay', 15), C('sessions', 'Attended sessions', 'int', 9),
    C('revenue', 'Revenue', 'money', 12), C('clinician_pay', 'Clinician pay', 'money', 12), C('employer_cost', 'Employer cost', 'money', 12), C('room_cost', 'Room cost', 'money', 11), C('admin_cost', 'Admin cost', 'money', 11),
    C('supervision_cost', 'Supervision cost', 'money', 11),
    CA('all_in_cost', 'All-in cost', 'money', '{col:clinician_pay}+{col:employer_cost}+{col:room_cost}+{col:admin_cost}+{col:supervision_cost}', 12),
    CA('margin', 'Practice margin', 'money', '{col:revenue}-{col:all_in_cost}', 12),
    CA('cost_per_session', 'All-in cost per session', 'money', 'IF({col:sessions}>0,{col:all_in_cost}/{col:sessions},0)', 11),
    CA('margin_per_session', 'Margin per session', 'money', 'IF({col:sessions}>0,{col:margin}/{col:sessions},0)', 11),
    CA('margin_share', 'Margin share of revenue', 'pct', 'IF({col:revenue}>0,{col:margin}/{col:revenue},0)', 11),
    CA('all_in_share', 'All-in cost share of revenue', 'pct', 'IF({col:revenue}>0,{col:all_in_cost}/{col:revenue},0)', 11),
    CA('margin_flag', 'Margin check', 'text', 'IF({col:margin_share}>={set:profit_target},%s,%s)' % (V('Margin on target'), V('Below target')), 14), PH('clinician')] + OWN()

